  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*if the current sale exist and not complete
   *and is ready to pay
   *and the input amount is greater or equal to the current sale amount
   *then create a new cash payment with the amount tendered with amount and the payment belonged sale is current sale
   *and current sale's assoicated payment is the payment and the current sale's belonged store is current store
   *and the current store will add this sale then the current sale is complete and the time is now
   *and the payment balance is equal to the input amount minus the current sale amount, then save the cash payment*/
  makeCashPayment(amount: number): boolean {
    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(this.CurrentSale) === false,
        description: "self.CurrentSale.oclIsUndefined()=false",
      })
        .and({
          logic: () => this.CurrentSale.IsComplete === false,
          description: "self.CurrentSale.IsComplete=false",
        })
        .and({
          logic: () => this.CurrentSale.IsReadytoPay === true,
          description: "self.CurrentSale.IsReadytoPay=true",
        })
        .and({
          logic: () => amount >= this.CurrentSale.Amount,
          description: "amount>=self.CurrentSale.Amount",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newPayment: CashPayment;
    return l({
      execute: () => (newPayment = new CashPayment()),
      description: "newPayment.oclIsNew()",
    })
      .and({
        execute: () => getRepository(CashPayment).push(newPayment),
        description: "CashPayment.allInstance()->includes(newPayment)",
      })
      .and({
        execute: () => (newPayment.AmountTendered = amount),
        description: "newPayment.AmountTendered=amount",
      })
      .and({
        execute: () => (newPayment.BelongedSale = this.CurrentSale),
        description: "newPayment.BelongedSale=self.CurrentSale",
      })
      .and({
        execute: () => (this.CurrentSale.AssoicatedPayment = newPayment),
        description: "self.CurrentSale.AssoicatedPayment=newPayment",
      })
      .and({
        execute: () => this.CurrentSale.Belongedstore,
        description: "self.CurrentSale.Belongedstore",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { ProcessSaleService_AutoGenerated };

